//! 🧪️ Native Tick construction retains original segmented input and physical recipient custody.
use super::*;
use semio_framework_value_native_owned::native_decoding::NativeDecodeConstructionRecipient;
struct Source<'a>{bytes:&'a[u8],page:usize}
impl OriginalTickWireSource for Source<'_>{fn identity(&self)->usize{self.bytes.as_ptr()as usize}fn byte_len(&self)->usize{self.bytes.len()}fn page(&self,index:usize)->Option<&[u8]>{let start=index.checked_mul(self.page)?;if start>=self.bytes.len(){return None}self.bytes.get(start..(start+self.page).min(self.bytes.len()))}}
struct Recipient{grant:RetainedCloneGrant,spent:RetainedCloneProgress}
impl NativeDecodeConstructionRecipient for Recipient{fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)}fn accept(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{assert!(progress.fits(grant));self.spent=self.spent.checked_add(progress)?;Ok(())}}
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn large()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:131072,maximum_release_bytes:131072,maximum_depth:64}}
fn close(cursor:&mut ToolRunTickNativeCursor){let mut rounds=0;while !cursor.terminal_is_empty(){let d=cursor.close_demands(4096).unwrap();let grant=RetainedCloneGrant{maximum_copy_bytes:4096,..exact(d)};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);rounds+=1;assert!(rounds<100000);}}
fn retire<T:semio_framework_value::retirement::RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original native Tick retirement issuer"));while !owner.terminal_is_empty(){let d=owner.next_demand(4096).unwrap();owner.step(RetainedCloneGrant{maximum_copy_bytes:4096,..exact(d)}).unwrap();}}
#[test]
fn original_payload_stream_native_tick_receive_preserves_every_field_and_original_pages(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for count in law["counts"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;let identity=ToolRunIdentity::new(ToolRunId{app_instance_id:7,run:11},[17;32]);let mut writer=ToolRunTickWriter::new(identity);writer.payload(vec![120;law["payloadBytes"].as_u64().unwrap()as usize]);writer.append_ops=(0..count).map(|index|vec![index as u8,255]).collect();writer.append_entities=(0..count as u64).collect();writer.steps=(0..count).map(|index|ToolRunStep{sequence:index as u64,kind:ToolRunStepKind::Success,stage:2,reason:4,subject:Some(index as u64),repeat:3,args:vec![ToolRunStepArg::Unsigned(index as u64),ToolRunStepArg::Float(-0.0)]}).collect();writer.progress=Some(ToolRunProgress{identity,sequence:3,state:ToolRunState::Running,stage:2,completed:count as u64,total:Some(count as u64),counters:vec![ToolRunCounter{counter:3,value:u64::MAX}],units_per_second:-0.0,conflicts:7,steps:ToolRunStepRing::from_steps(writer.steps.clone()).unwrap()});writer.pages=vec![ToolRunTracePage{identity,page:7,ops:vec![ToolRunTraceOp::Clear,ToolRunTraceOp::Retire{key:u64::MAX},ToolRunTraceOp::Upsert{key:4,verdict:ToolRunVerdict::Warning,reason:3,subject:ToolRunTraceSubject::Entity{entity:19}},ToolRunTraceOp::Upsert{key:5,verdict:ToolRunVerdict::Success,reason:5,subject:ToolRunTraceSubject::Instance3d{mesh:2,position:[1.,-0.0,3.],rotation:[0.,0.,0.,1.],scale:2.}},ToolRunTraceOp::Upsert{key:6,verdict:ToolRunVerdict::Danger,reason:7,subject:ToolRunTraceSubject::Placement2d{shape:3,position:[-1.,0.],rotation:0.25}}]}];let expected=writer.finish().unwrap();let wire=expected.encode().unwrap();let source=Source{bytes:&wire,page:law["sourcePageBytes"].as_u64().unwrap()as usize};let mut cursor=ToolRunTickNativeCursor::empty();let birth=cursor.admit(&source,large()).unwrap().unwrap();assert!(birth.fits(large()));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let ledger=control.ledger_identity();let mut rounds=0;
  while !cursor.is_complete(){let demand=cursor.next_demands().unwrap();let grant=exact(demand);for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant}]{let before=(cursor.consumed_bytes(),cursor.depth,cursor.pending);let mut recipient=Recipient{grant:denied,spent:Default::default()};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||control.with_construction_recipient(&mut recipient,|native|cursor.advance(&source,native)).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(before,(cursor.consumed_bytes(),cursor.depth,cursor.pending));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let mut recipient=Recipient{grant,spent:Default::default()};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||control.with_construction_recipient(&mut recipient,|native|cursor.advance(&source,native)).unwrap());assert_eq!(step.progress(),recipient.spent);assert!(step.progress().fits(grant));assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);assert_eq!(ledger,control.ledger_identity());rounds+=1;assert!(rounds<250000);}
  let(actual,_)=cursor.take_output(large()).unwrap();assert_eq!(actual,expected);close(&mut cursor);let((),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(cursor));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));retire(actual);println!("[DEBUG] original native Tick count={count} turns={rounds} bytes={} original17bytePages=true allFields=true physicalReceipts=true terminalDrop0=true",wire.len());
 }
}
#[test]
fn original_payload_stream_native_tick_receive_closes_cancelled_prefixes(){let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let identity=ToolRunIdentity::new(ToolRunId{app_instance_id:7,run:11},[17;32]);let mut writer=ToolRunTickWriter::new(identity);writer.payload(vec![19;129]);let wire=writer.finish().unwrap().encode().unwrap();let source=Source{bytes:&wire,page:17};for prefix in law["cancelPrefixes"].as_array().unwrap(){let mut cursor=ToolRunTickNativeCursor::empty();cursor.admit(&source,large()).unwrap().unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);for _ in 0..prefix.as_u64().unwrap(){if cursor.is_complete(){break}let grant=exact(cursor.next_demands().unwrap());let mut recipient=Recipient{grant,spent:Default::default()};control.with_construction_recipient(&mut recipient,|native|cursor.advance(&source,native)).unwrap();}close(&mut cursor);let((),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(cursor));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));println!("[DEBUG] original native Tick cancelled prefix={prefix} originalPagesUntouched=true terminalDrop0=true");}}
